```tsx
import type { ReactNode } from "react";

type PanelHeaderProps = {
  title: string;
  actionLabel?: string;
  onAction?: () => void;
  actionIcon?: ReactNode;
  className?: string;
};

export function PanelHeader({
  title,
  actionLabel = "Action",
  onAction,
  actionIcon,
  className = "",
}: PanelHeaderProps) {
  return (
    <header
      className={`flex items-center justify-between gap-3 p-3 rounded-lg border border-zinc-800 bg-zinc-900 ${className}`}
    >
      <h2 className="text-sm font-semibold text-zinc-100 truncate">
        {title}
      </h2>

      <button
        type="button"
        onClick={onAction}
        className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-md border border-zinc-800 bg-zinc-800 text-xs font-medium text-zinc-300 hover:bg-zinc-700 hover:text-zinc-100 transition-colors"
      >
        {actionIcon && <span className="text-zinc-400">{actionIcon}</span>}
        {actionLabel}
      </button>
    </header>
  );
}
```

